fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    let len = dst.len();
    assert_eq!(src.len(), len, "src and dst must have the same length");
    assert_eq!(mask.len(), len, "mask length must match dst and src");

    let mut result = Vec::with_capacity(len);
    for i in 0..len {
        if mask[i] {
            result.push(src[i]);
        } else {
            result.push(dst[i]);
        }
    }
    result
}